def word_count(tale):
    """Words in a tale, counted the same way the player counts them."""
    return sum(len(paragraph.split()) for paragraph in tale["paragraphs"])


def estimated_minutes(tale):
    """Minutes a tale takes to read aloud at the measured calm pace."""
    return word_count(tale) / READ_ALOUD_WPM
